@@ -0,0 +1,61 @@
+package com.tanya.workrequests.domain;
+
+import org.junit.jupiter.api.Test;
+
+import java.util.Arrays;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+/** Pins the STALE code and the Problem.stale factory. */
+class StalenessProblemTest {
+
+    @Test
+    void problemCodeContainsStaleAlongsideTheExistingCodes() {
+        assertThat(Arrays.stream(ProblemCode.values()).map(Enum::name))
+                .containsExactlyInAnyOrder("NULL_REQUEST", "MISSING_FIELD", "INVALID_VALUE",
+                        "DUPLICATE", "CONFLICTING_REQUEST_ID", "STALE");
+    }
+
+    @Test
+    void staleCarriesTheInputIndexItWasGiven() {
+        assertThat(Problem.stale(3, "R-7", 30).inputIndex()).isEqualTo(3);
+    }
+
+    @Test
+    void staleCarriesTheRequestIdItWasGiven() {
+        assertThat(Problem.stale(3, "R-7", 30).requestId()).isEqualTo("R-7");
+    }
+
+    @Test
+    void staleUsesTheStaleProblemCode() {
+        assertThat(Problem.stale(3, "R-7", 30).code()).isEqualTo(ProblemCode.STALE);
+    }
+
+    @Test
+    void staleMessageNamesTheRequestIdAndTheMaxAgeInDays() {
+        assertThat(Problem.stale(3, "R-7", 30).message()).isEqualTo("R-7 is older than 30 days");
+    }
+
+    @Test
+    void staleMessageUsesTheMaxAgeDayCountItWasGiven() {
+        assertThat(Problem.stale(0, "R-9", 7).message()).isEqualTo("R-9 is older than 7 days");
+    }
+
+    @Test
+    void staleLeavesTheFieldUnset() {
+        assertThat(Problem.stale(1, "R-2", 30).field()).isNull();
+    }
+
+    @Test
+    void staleLeavesTheRelatedRequestIdUnset() {
+        assertThat(Problem.stale(1, "R-2", 30).relatedRequestId()).isNull();
+    }
+
+    @Test
+    void staleLeavesBothEscalationFieldsUnset() {
+        Problem problem = Problem.stale(1, "R-2", 30);
+
+        assertThat(problem.escalatedFrom()).isNull();
+        assertThat(problem.escalatedTo()).isNull();
+    }
+}
diff --git a/backend/src/test/java/com/tanya/workrequests/processing/StalenessValidationTest.java b/backend/src/test/java/com/tanya/workrequests/processing/StalenessValidationTest.java
new file mode 100644
--- /dev/null
+++ b/backend/src/test/java/com/tanya/workrequests/processing/StalenessValidationTest.java
@@ -0,0 +1,177 @@
+package com.tanya.workrequests.processing;
+
+import com.tanya.workrequests.domain.Priority;
+import com.tanya.workrequests.domain.Problem;
+import com.tanya.workrequests.domain.StageTrace;
+import com.tanya.workrequests.domain.WorkRequest;
+import org.junit.jupiter.api.Test;
+
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.time.ZoneOffset;
+import java.util.ArrayList;
+import java.util.List;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+/**
+ * Staleness is reported inside the validate stage, and only when a Clock is supplied.
+ * "Now" is always the fixed clock, never the real date.
+ */
+class StalenessValidationTest {
+
+    private static final Clock FIXED_CLOCK =
+            Clock.fixed(Instant.parse("2026-10-29T00:00:00Z"), ZoneOffset.UTC);
+
+    private final WorkRequestValidator validator =
+            new WorkRequestValidator(FIXED_CLOCK, Duration.ofDays(30));
+
+    @Test
+    void validatorBuiltWithoutAClockNeverReportsStaleProblems() {
+        StageResult result = new WorkRequestValidator()
+                .validate(List.of(dated("R-1", "2001-01-01T00:00:00Z")));
+
+        assertThat(result.problems()).isEmpty();
+    }
+
+    @Test
+    void validatorBuiltWithoutAClockKeepsAncientRequests() {
+        WorkRequest ancient = dated("R-1", "2001-01-01T00:00:00Z");
+
+        StageResult result = new WorkRequestValidator().validate(List.of(ancient));
+
+        assertThat(result.requests()).containsExactly(new IndexedRequest(0, ancient));
+    }
+
+    @Test
+    void validatorBuiltWithoutAClockTracesAncientRequestsAsAccepted() {
+        StageResult result = new WorkRequestValidator()
+                .validate(List.of(dated("R-1", "2001-01-01T00:00:00Z")));
+
+        assertThat(result.trace()).isEqualTo(new StageTrace("validate", 1, 1, List.of()));
+    }
+
+    @Test
+    void reportsExactlyOneStaleProblemForARequestOlderThanMaxAge() {
+        StageResult result = validator.validate(List.of(dated("R-1", "2026-09-01T00:00:00Z")));
+
+        assertThat(result.problems()).containsExactly(Problem.stale(0, "R-1", 30));
+    }
+
+    @Test
+    void keepsAStaleRequestOutOfTheRequestsThatReachTheNextStage() {
+        StageResult result = validator.validate(List.of(dated("R-1", "2026-09-01T00:00:00Z")));
+
+        assertThat(result.requests()).isEmpty();
+    }
+
+    @Test
+    void acceptsARequestWhoseAgeIsExactlyMaxAge() {
+        WorkRequest exactlyThirtyDaysOld = dated("R-1", "2026-09-29T00:00:00Z");
+
+        StageResult result = validator.validate(List.of(exactlyThirtyDaysOld));
+
+        assertThat(result.problems()).isEmpty();
+        assertThat(result.requests()).containsExactly(new IndexedRequest(0, exactlyThirtyDaysOld));
+    }
+
+    @Test
+    void reportsStaleForARequestOneSecondOlderThanMaxAge() {
+        WorkRequest justOverThirtyDaysOld = dated("R-1", "2026-09-28T23:59:59Z");
+
+        StageResult result = validator.validate(List.of(justOverThirtyDaysOld));
+
+        assertThat(result.problems()).containsExactly(Problem.stale(0, "R-1", 30));
+        assertThat(result.requests()).isEmpty();
+    }
+
+    @Test
+    void acceptsAFutureDatedRequest() {
+        WorkRequest futureDated = dated("R-1", "2026-11-05T00:00:00Z");
+
+        StageResult result = validator.validate(List.of(futureDated));
+
+        assertThat(result.problems()).isEmpty();
+        assertThat(result.requests()).containsExactly(new IndexedRequest(0, futureDated));
+    }
+
+    @Test
+    void doesNotReportStaleForARequestWithoutARequestedAt() {
+        WorkRequest withoutTimestamp =
+                TestRequests.request("R-1", "EQ-1", Priority.MEDIUM, null, "Work for R-1");
+
+        StageResult result = validator.validate(List.of(withoutTimestamp));
+
+        assertThat(result.problems()).containsExactly(Problem.missingField(0, "R-1", "requestedAt"));
+    }
+
+    @Test
+    void doesNotAddStaleToARequestThatAlreadyFailsAFieldCheck() {
+        WorkRequest staleAndIncomplete = TestRequests.request("R-2", null, Priority.MEDIUM,
+                "2026-07-21T00:00:00Z", "Work for R-2");
+
+        StageResult result = validator.validate(List.of(staleAndIncomplete));
+
+        assertThat(result.problems()).containsExactly(Problem.missingField(0, "R-2", "equipmentId"));
+    }
+
+    @Test
+    void doesNotAddStaleToANullRequest() {
+        List<WorkRequest> batchWithNull = new ArrayList<>();
+        batchWithNull.add(null);
+
+        StageResult result = validator.validate(batchWithNull);
+
+        assertThat(result.problems()).containsExactly(Problem.nullRequest(0));
+    }
+
+    @Test
+    void tracesStaleRequestsAsRejectedWithinTheValidateStage() {
+        StageResult result = validator.validate(batchWithTwoStaleAndTwoFreshRequests());
+
+        assertThat(result.trace()).isEqualTo(new StageTrace("validate", 4, 2,
+                List.of("R-1 rejected: stale", "R-2 rejected: stale")));
+    }
+
+    @Test
+    void keepsOnlyTheFreshRequestsOfAPartlyStaleBatch() {
+        StageResult result = validator.validate(batchWithTwoStaleAndTwoFreshRequests());
+
+        assertThat(result.requests().stream().map(IndexedRequest::request).map(WorkRequest::requestId))
+                .containsExactly("R-3", "R-4");
+    }
+
+    @Test
+    void reportsStaleProblemsInAscendingInputIndexOrder() {
+        StageResult result = validator.validate(batchWithTwoStaleAndTwoFreshRequests());
+
+        assertThat(result.problems())
+                .containsExactly(Problem.stale(0, "R-1", 30), Problem.stale(1, "R-2", 30));
+    }
+
+    @Test
+    void takesTheDayCountInTheMessageFromTheConfiguredMaxAge() {
+        WorkRequestValidator sevenDayValidator =
+                new WorkRequestValidator(FIXED_CLOCK, Duration.ofDays(7));
+
+        List<Problem> problems = sevenDayValidator
+                .validate(List.of(dated("R-1", "2026-10-19T00:00:00Z"))).problems();
+
+        assertThat(problems).hasSize(1);
+        assertThat(problems.get(0).message()).isEqualTo("R-1 is older than 7 days");
+    }
+
+    private static List<WorkRequest> batchWithTwoStaleAndTwoFreshRequests() {
+        return List.of(dated("R-1", "2026-09-01T00:00:00Z"),
+                dated("R-2", "2026-09-02T00:00:00Z"),
+                dated("R-3", "2026-10-20T08:00:00Z"),
+                dated("R-4", "2026-10-21T08:00:00Z"));
+    }
+
+    /** A complete, valid request whose only variable is when it was raised. */
+    private static WorkRequest dated(String requestId, String requestedAt) {
+        return TestRequests.request(requestId, "EQ-" + requestId, Priority.MEDIUM, requestedAt,
+                "Work for " + requestId);
+    }
+}
diff --git a/backend/src/test/java/com/tanya/workrequests/processing/StaleRequestProcessingTest.java b/backend/src/test/java/com/tanya/workrequests/processing/StaleRequestProcessingTest.java
new file mode 100644
--- /dev/null
+++ b/backend/src/test/java/com/tanya/workrequests/processing/StaleRequestProcessingTest.java
@@ -0,0 +1,172 @@
+package com.tanya.workrequests.processing;
+
+import com.tanya.workrequests.domain.Priority;
+import com.tanya.workrequests.domain.Problem;
+import com.tanya.workrequests.domain.ProblemCode;
+import com.tanya.workrequests.domain.ProcessingResult;
+import com.tanya.workrequests.domain.StageTrace;
+import com.tanya.workrequests.domain.WorkRequest;
+import org.junit.jupiter.api.Test;
+
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.time.ZoneOffset;
+import java.util.ArrayList;
+import java.util.List;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+/**
+ * A stale request is dropped by validation, so deduplication never sees it even when it is
+ * the earliest copy of a duplicate group.
+ */
+class StaleRequestProcessingTest {
+
+    private static final Clock FIXED_CLOCK =
+            Clock.fixed(Instant.parse("2026-10-29T00:00:00Z"), ZoneOffset.UTC);
+
+    private static final WorkRequest FRESH_ORIGINAL = TestRequests.request(
+            "R-1", "EQ-9", Priority.MEDIUM, "2026-10-20T08:00:00Z", "Pump leak");
+    /** Older than maxAge and the earliest copy, so it would be kept if dedup ever saw it. */
+    private static final WorkRequest STALE_COPY = TestRequests.request(
+            "R-2", "EQ-9", Priority.MEDIUM, "2026-09-01T00:00:00Z", "Pump leak");
+    private static final WorkRequest FRESH_COPY = TestRequests.request(
+            "R-3", "EQ-9", Priority.MEDIUM, "2026-10-21T08:00:00Z", "Pump leak");
+    private static final WorkRequest INCOMPLETE = TestRequests.request(
+            "R-4", null, Priority.MEDIUM, "2026-10-22T08:00:00Z", "Belt replacement");
+
+    private static final List<WorkRequest> BATCH =
+            List.of(FRESH_ORIGINAL, STALE_COPY, FRESH_COPY, INCOMPLETE);
+
+    private final WorkRequestProcessor processor = new WorkRequestProcessor(
+            new WorkRequestValidator(FIXED_CLOCK, Duration.ofDays(30)),
+            new DuplicateResolver(new DescriptionNormalizer()),
+            new WorkRequestSorter());
+
+    @Test
+    void reportsOnlyStaleForAStaleDuplicateBecauseDeduplicationNeverSeesIt() {
+        List<ProblemCode> codes = processor.process(BATCH).problems().stream()
+                .filter(problem -> "R-2".equals(problem.requestId()))
+                .map(Problem::code)
+                .toList();
+
+        assertThat(codes).containsExactly(ProblemCode.STALE);
+    }
+
+    @Test
+    void keepsTheFreshOriginalRatherThanTheEarlierStaleCopy() {
+        assertThat(ids(processor.process(BATCH).accepted())).containsExactly("R-1");
+    }
+
+    @Test
+    void listsValidateStageProblemsBeforeDeduplicateStageProblems() {
+        assertThat(processor.process(BATCH).problems()).containsExactly(
+                Problem.stale(1, "R-2", 30),
+                Problem.missingField(3, "R-4", "equipmentId"),
+                Problem.duplicate(2, "R-3", "R-1"));
+    }
+
+    @Test
+    void tracesExactlyTheThreeExistingStages() {
+        List<String> stages = processor.process(BATCH).trace().stream()
+                .map(StageTrace::stage)
+                .toList();
+
+        assertThat(stages).containsExactly("validate", "deduplicate", "prioritize");
+    }
+
+    @Test
+    void countsStaleRequestsAsRejectedByTheValidateStage() {
+        StageTrace validate = processor.process(BATCH).trace().get(0);
+
+        assertThat(validate.in()).isEqualTo(4);
+        assertThat(validate.out()).isEqualTo(2);
+    }
+
+    @Test
+    void notesTheStaleRejectionByRequestIdInTheValidateStage() {
+        StageTrace validate = processor.process(BATCH).trace().get(0);
+
+        assertThat(validate.notes()).contains("R-2 rejected: stale");
+    }
+
+    @Test
+    void producesTheSameAcceptedQueueForEveryInputOrder() {
+        List<String> expected = ids(processor.process(BATCH).accepted());
+
+        for (List<WorkRequest> order : permutations(BATCH)) {
+            assertThat(ids(processor.process(order).accepted())).isEqualTo(expected);
+        }
+    }
+
+    @Test
+    void producesTheSameTraceForEveryInputOrder() {
+        List<StageTrace> expected = processor.process(BATCH).trace();
+
+        for (List<WorkRequest> order : permutations(BATCH)) {
+            assertThat(processor.process(order).trace()).isEqualTo(expected);
+        }
+    }
+
+    @Test
+    void producesTheSameProblemsForEveryInputOrder() {
+        List<String> expected = signatures(processor.process(BATCH));
+
+        for (List<WorkRequest> order : permutations(BATCH)) {
+            assertThat(signatures(processor.process(order)))
+                    .containsExactlyInAnyOrderElementsOf(expected);
+        }
+    }
+
+    @Test
+    void keepsTheDeduplicateStageProblemLastForEveryInputOrder() {
+        for (List<WorkRequest> order : permutations(BATCH)) {
+            List<Problem> problems = processor.process(order).problems();
+
+            assertThat(problems.get(problems.size() - 1).code()).isEqualTo(ProblemCode.DUPLICATE);
+        }
+    }
+
+    @Test
+    void ordersValidateStageProblemsByInputIndexForEveryInputOrder() {
+        for (List<WorkRequest> order : permutations(BATCH)) {
+            List<Integer> indices = processor.process(order).problems().stream()
+                    .filter(problem -> problem.code() != ProblemCode.DUPLICATE)
+                    .map(Problem::inputIndex)
+                    .toList();
+
+            assertThat(indices).isSorted();
+        }
+    }
+
+    /** Problem identity without the input index, which legitimately moves with the input order. */
+    private static List<String> signatures(ProcessingResult result) {
+        return result.problems().stream()
+                .map(problem -> problem.code() + "|" + problem.requestId() + "|"
+                        + problem.relatedRequestId() + "|" + problem.message())
+                .toList();
+    }
+
+    private static List<String> ids(List<WorkRequest> requests) {
+        return requests.stream().map(WorkRequest::requestId).toList();
+    }
+
+    private static List<List<WorkRequest>> permutations(List<WorkRequest> requests) {
+        if (requests.isEmpty()) {
+            return List.of(List.of());
+        }
+        List<List<WorkRequest>> permutations = new ArrayList<>();
+        for (int index = 0; index < requests.size(); index++) {
+            List<WorkRequest> rest = new ArrayList<>(requests);
+            WorkRequest head = rest.remove(index);
+            for (List<WorkRequest> tail : permutations(rest)) {
+                List<WorkRequest> permutation = new ArrayList<>();
+                permutation.add(head);
+                permutation.addAll(tail);
+                permutations.add(permutation);
+            }
+        }
+        return permutations;
+    }
+}
diff --git a/backend/src/test/java/com/tanya/workrequests/config/StalenessPropertiesTest.java b/backend/src/test/java/com/tanya/workrequests/config/StalenessPropertiesTest.java
